/* static/styles.css */

/* General Reset */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Body Styling */
body {
  font-family: Arial, sans-serif;
  line-height: 1.6;
  background-color: #f9f9f9;
  color: #333;
  margin: 0;
  padding: 0;
}

/* Header Styling */
header {
  background-color: #4CAF50;
  color: white;
  padding: 1rem 2rem;
  text-align: center;
  font-size: 1.5rem;
}

/* Main Content Styling */
main {
  max-width: 800px;
  margin: 2rem auto;
  padding: 1rem;
  background: white;
  border: 1px solid #ddd;
  border-radius: 5px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

/* Note List Styling */
.note-list {
  list-style-type: none;
  padding: 0;
}

.note-list li {
  background: #f1f1f1;
  margin-bottom: 1rem;
  padding: 1rem;
  border: 1px solid #ddd;
  border-radius: 5px;
  transition: background-color 0.3s ease;
}

.note-list li:hover {
  background: #e9ecef;
}

/* Note Details Styling */
.note {
  padding: 1rem;
  border: 1px solid #ddd;
  border-radius: 5px;
  margin-bottom: 1rem;
  background: #fff;
}

/* Buttons */
button {
  display: inline-block;
  background-color: #4CAF50;
  color: white;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 3px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

button:hover {
  background-color: #45a049;
}

button.delete {
  background-color: #f44336;
}

button.delete:hover {
  background-color: #da190b;
}

/* Form Styling */
form {
  margin-bottom: 2rem;
}

form input[type="text"],
form textarea {
  width: 100%;
  padding: 0.5rem;
  margin-bottom: 1rem;
  border: 1px solid #ddd;
  border-radius: 5px;
}

form textarea {
  resize: vertical;
}

form button {
  float: right;
}

/* Clear Fix */
.clearfix::after {
  content: "";
  display: table;
  clear: both;
}

/* Search Bar */
.search-bar {
  margin-bottom: 1.5rem;
}

.search-bar input[type="text"] {
  width: calc(100% - 70px);
  padding: 0.5rem;
  border: 1px solid #ddd;
  border-radius: 5px 0 0 5px;
  outline: none;
}

.search-bar button {
  width: 70px;
  border-radius: 0 5px 5px 0;
}

/* Footer Styling */
footer {
  text-align: center;
  padding: 1rem;
  margin-top: 2rem;
  background: #f1f1f1;
  color: #777;
  font-size: 0.9rem;
  border-top: 1px solid #ddd;
}
